{"status":"candidate","chosen_option":"constrained_selection","assumptions":["Input follows the stated format and contains only '(' , ')' and '?' characters.","The implementation uses C++17."],"observations":[{"statement":"The assignment must satisfy every prefix balance constraint and end with total balance zero; each '?' has separate open and close costs.","source_ids":["task"]},{"statement":"The string length is at most 200000 and each cost is at most 1000000000, so 64-bit integers safely hold accumulated costs.","source_ids":["task"]}],"artifact":{"code":"#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    if (!(cin >> s)) return 0;

    // Start with every '?' assigned ')'. Selecting a '?' to be '(' adds
    // 2 to the balance and costs open_cost - close_cost.
    long long baseBalance = 0;
    long long totalCost = 0;
    long long selected = 0;
    long long required = 0;
    priority_queue<long long, vector<long long>, greater<long long>> available;
    bool possible = true;

    for (char c : s) {
        if (c == '(') {
            ++baseBalance;
        } else if (c == ')') {
            --baseBalance;
        } else { // '?'
            long long openCost, closeCost;
            cin >> openCost >> closeCost;
            totalCost += closeCost;
            available.push(openCost - closeCost);
            --baseBalance; // baseline assignment is ')'
        }

        // Prefix balance is baseBalance + 2 * selected >= 0.
        long long need = baseBalance < 0 ? (-baseBalance + 1) / 2 : 0;
        required = max(required, need);
        while (selected < required) {
            if (available.empty()) {
                possible = false;
                break;
            }
            totalCost += available.top();
            available.pop();
            ++selected;
        }
        if (!possible) break;
    }

    if (!possible) {
        cout << -1 << '\n';
        return 0;
    }

    // The final balance must be zero: baseBalance + 2*K = 0.
    if (baseBalance % 2 != 0) {
        cout << -1 << '\n';
        return 0;
    }
    long long target = -baseBalance / 2;
    if (target < selected || target > selected + (long long)available.size()) {
        cout << -1 << '\n';
        return 0;
    }

    // Meet the exact final count as cheaply as possible from remaining '?'.
    while (selected < target) {
        totalCost += available.top();
        available.pop();
        ++selected;
    }

    cout << totalCost << '\n';
    return 0;
}
